+thread_local! {
+    static THIN_PROFILE: Cell<u8> = const { Cell::new(0) };
+}
+
+pub struct ThinProfileGuard {
+    prev: u8,
+}
+
+impl Drop for ThinProfileGuard {
+    fn drop(&mut self) {
+        THIN_PROFILE.with(|profile| profile.set(self.prev));
+    }
+}
+
+pub fn enter_cancel_profile() -> ThinProfileGuard {
+    THIN_PROFILE.with(|profile| {
+        let prev = profile.replace(1);
+        ThinProfileGuard { prev }
+    })
+}

